{"content":"1|//! Principal-bound capability-grant materializer.
2|//!
3|//! The durable document lives under `/etc`; consumers read a root-only atomic
4|//! projection in tmpfs. Validation happens before every projection so wildcard
5|//! and legacy footprint authority can never be published accidentally.
6|
7|use std::fs::{self, File, OpenOptions};
8|use std::io::Write;
9|use std::os::unix::fs::{OpenOptionsExt, PermissionsExt};
10|use std::path::{Path, PathBuf};
11|use std::time::{Duration, SystemTime, UNIX_EPOCH};
12|
13|use anyhow::{bail, Context, Result};
14|use op_grpc_bridge::mcp_policy::{parse_audience_policy, parse_toolset_manifest};
15|
16|const DEFAULT_SOURCE: &str = "/etc/opdbus/capability-grants.json";
17|const DEFAULT_TARGET: &str = "/dev/shm/opdbus/capability-grants.json";
18|const DEFAULT_READY: &str = "/run/opdbus/runit-ready/opdbus-grants";
19|const INVALID_DOCUMENT: &[u8] = b"{}\n";
20|
21|#[derive(Debug, Clone, Copy, PartialEq, Eq)]
22|enum ReconcileState {
23|    Fresh,
24|    Materialized,
25|}
26|
27|fn validate_document(bytes: &[u8]) -> Result<()> {
28|    op_grpc_bridge::interceptor::validate_grant_document(bytes)
29|        .map_err(|error| anyhow::anyhow!(error))
30|}
31|
32|fn atomic_write(path: &Path, bytes: &[u8], mode: u32) -> Result<()> {
33|    let parent = path
34|        .parent()
35|        .with_context(|| format!("{} has no parent directory", path.display()))?;
36|    fs::create_dir_all(parent)
37|        .with_context(|| format!("create projection directory {}", parent.display()))?;
38|
39|    let file_name = path
40|        .file_name()
41|        .and_then(|name| name.to_str())
42|        .context("projection path has no UTF-8 file name")?;
43|    let nonce = SystemTime::now()
44|        .duration_since(UNIX_EPOCH)
45|        .unwrap_or_default()
46|        .as_nanos();
47|    let temporary = parent.join(format!(".{file_name}.{}.{nonce}.tmp", std::process::id()));
48|
49|    let write_result = (|| -> Result<()> {
50|        let mut output = OpenOptions::new()
51|            .write(true)
52|            .create_new(true)
53|            .mode(mode)
54|            .open(&temporary)
55|            .with_context(|| format!("create temporary projection {}", temporary.display()))?;
56|        output
57|            .write_all(bytes)
58|            .with_context(|| format!("write temporary projection {}", temporary.display()))?;
59|        output
60|            .sync_all()
61|            .with_context(|| format!("sync temporary projection {}", temporary.display()))?;
62|        fs::rename(&temporary, path).with_context(|| {
63|            format!(
64|                "atomically replace {} with {}",
65|                path.display(),
66|                temporary.display()
67|            )
68|        })?;
69|        fs::set_permissions(path, fs::Permissions::from_mode(mode))
70|            .with_context(|| format!("set permissions on {}", path.display()))?;
71|        File::open(parent)
72|            .and_then(|directory| directory.sync_all())
73|            .with_context(|| format!("sync projection directory {}", parent.display()))?;
74|        Ok(())
75|    })();
76|
77|    if write_result.is_err() {
78|        let _ = fs::remove_file(&temporary);
79|    }
80|    write_result
81|}
82|
83|fn remove_ready(ready: &Path) {
84|    match fs::remove_file(ready) {
85|        Ok(()) => {}
86|        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
87|        Err(error) => eprintln!("grants materializer: remove {}: {error}", ready.display()),
88|    }
89|}
90|
91|fn mark_ready(ready: &Path) -> Result<()> {
92|    atomic_write(ready, b"ready\n", 0o644)
93|}
94|
95|fn read_valid_source(source: &Path) -> Result<Vec<u8>> {
96|    let bytes = fs::read(source)
97|        .with_context(|| format!("durable grant source unreadable: {}", source.display()))?;
98|    validate_document(&bytes)?;
99|    Ok(bytes)
100|}
101|
102|fn reconcile(source: &Path, target: &Path, ready: &Path) -> Result<ReconcileState> {
103|    let source_bytes = match read_valid_source(source) {
104|        Ok(bytes) => bytes,
105|        Err(error) => {
106|            remove_ready(ready);
107|            if fs::read(target).ok().as_deref() != Some(INVALID_DOCUMENT) {
108|                atomic_write(target, INVALID_DOCUMENT, 0o600)
109|                    .context("publish fail-closed empty grant projection")?;
110|            }
111|            return Err(error);
112|        }
113|    };
114|
115|    let target_fresh = fs::read(target)
116|        .map(|bytes| bytes == source_bytes)
117|        .unwrap_or(false);
118|    let target_mode = fs::metadata(target)
119|        .map(|metadata| metadata.permissions().mode() & 0o777)
120|        .ok();
121|    let state = if target_fresh && target_mode == Some(0o600) {
122|        ReconcileState::Fresh
123|    } else {
124|        atomic_write(target, &source_bytes, 0o600)?;
125|        ReconcileState::Materialized
126|    };
127|    mark_ready(ready)?;
128|    Ok(state)
129|}
130|
131|fn check(source: &Path, target: &Path) -> Result<bool> {
132|    let source_bytes = read_valid_source(source)?;
133|    let target_bytes = fs::read(target)
134|        .with_context(|| format!("grant projection unreadable: {}", target.display()))?;
135|    validate_document(&target_bytes).context("grant projection is invalid")?;
136|    let mode = fs::metadata(target)?.permissions().mode() & 0o777;
137|    Ok(source_bytes == target_bytes && mode == 0o600)
138|}
139|
140|fn paths() -> (PathBuf, PathBuf, PathBuf) {
141|    (
142|        std::env::var_os("OP_GRANTS_SOURCE")
143|            .map(PathBuf::from)
144|            .unwrap_or_else(|| PathBuf::from(DEFAULT_SOURCE)),
145|        std::env::var_os("OP_GRANTS_PATH")
146|            .map(PathBuf::from)
147|            .unwrap_or_else(|| PathBuf::from(DEFAULT_TARGET)),
148|        std::env::var_os("OP_GRANTS_READY")
149|            .map(PathBuf::from)
150|            .unwrap_or_else(|| PathBuf::from(DEFAULT_READY)),
151|    )
152|}
