470|fn bind_socket(path: &Path) -> Result<tokio::net::UnixListener> {
471|    if let Some(parent) = path.parent() {
472|        std::fs::create_dir_all(parent).with_context(|| format!("create {}", parent.display()))?;
473|    }
474|    match std::fs::symlink_metadata(path) {
475|        Ok(metadata) if metadata.file_type().is_socket() => std::fs::remove_file(path)?,
476|        Ok(_) => anyhow::bail!("{} exists and is not a socket", path.display()),
477|        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {}
478|        Err(error) => return Err(error.into()),
479|    }
480|    let listener =
481|        tokio::net::UnixListener::bind(path).with_context(|| format!("bind {}", path.display()))?;
482|    std::fs::set_permissions(path, std::fs::Permissions::from_mode(0o666))?;
483|    Ok(listener)
