436|#[zbus::interface(name = "org.opdbus.v1.LungsV1")]
437|impl LungsBootstrap {
438|    async fn bind(&self, session_id: String) -> zbus::fdo::Result<bool> {
439|        self.identity
440|            .bind(&session_id)
441|            .await
442|            .map_err(bootstrap_denial)?;
443|        Ok(true)
444|    }
