447|        tokio::time::timeout(NEGOTIATION_TIMEOUT, self.identity.bind_current_container())
448|            .await
449|            .map_err(|_| bootstrap_denial(anyhow::anyhow!("container binding timed out")))?
450|            .map_err(bootstrap_denial)?;
