460|fn valid_session_id(session_id: &str) -> bool {
461|    !session_id.is_empty()
462|        && session_id.len() <= 128
463|        && session_id
464|            .bytes()
465|            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-' || byte == b'_')
466|}
