600|fn complete(state: &Arc<Mutex<OpenFile>>, result: Execution) {
601|    let mut handle = state.lock();
602|    handle.running = false;
603|    let status = match result {
604|        Execution::Rejected(errno, mut bytes) => {
605|            if bytes.bytes.is_empty() {
606|                bytes = handle
607|                    .admission_fallback
608|                    .take()
609|                    .unwrap_or_else(|| Buffer::empty(&handle.bytes.charge_budget()));
610|            }
611|            handle.completed = Some(Err((errno, bytes)));
612|            Err(errno)
613|        }
614|        Execution::Call(mut result) => {
615|            if let Err((_, bytes)) = &mut result
616|                && bytes.bytes.is_empty()
617|                && let Some(fallback) = handle.fallback.take()
618|            {
619|                *bytes = fallback;
620|            }
621|            let status = result.as_ref().map(|_| ()).map_err(|(errno, _)| *errno);
622|            handle.completed = Some(result);
623|            status
624|        }
625|        Execution::Workspace(Ok((bytes, hash))) => {
626|            handle.bytes = bytes;
627|            if let Some(target) = &mut handle.node.write_target {
628|                target.expected_object_hash = hash;
629|            }
630|            Ok(())
631|        }
632|        Execution::Workspace(Err(errno)) => {
633|            // A failed staging attempt is terminal until reopen, so release
634|            // cannot silently retry a conflicting or malformed replacement.
635|            let empty = Buffer::empty(&handle.bytes.charge_budget());
636|            handle.completed = Some(Err((errno, empty)));
637|            Err(errno)
638|        }
639|    };
640|    handle.admission_fallback = None;
641|    let waiters = std::mem::take(&mut handle.waiters);
642|    drop(handle);
643|    for reply in waiters {
644|        reply_result(reply, status);
645|    }
