273|fn record_to_sled(
274|    record: &IdentitySledRecord,
275|    genesis: Option<&GenesisInputsRecord>,
276|) -> anyhow::Result<ContainerIdentitySled> {
277|    anyhow::ensure!(
278|        record.mutation_index >= 0,
279|        "negative durable mutation index"
280|    );
281|    anyhow::ensure!(
282|        record.schema_version >= 0,
283|        "negative durable schema version"
284|    );
285|    let mut sled = ContainerIdentitySled {
286|        session_id: record.session_id.clone(),
287|        wireguard_pubkey: record.wireguard_pubkey.clone(),
288|        interface: record.interface.clone(),
289|        peer_ip: (!record.peer_ip.is_empty()).then(|| record.peer_ip.clone()),
290|        mutation_index: u64::try_from(record.mutation_index)?,
291|        genesis: (!record.session_genesis.is_empty()).then(|| record.session_genesis.clone()),
292|        trace_id: record.trace_id.clone(),
293|        schema_version: u32::try_from(record.schema_version)?,
294|        vector_id: record.vector_id.clone(),
295|        sealed_id: (!record.sealed_id.is_empty()).then(|| record.sealed_id.clone()),
296|        principal_kind: record.principal_kind.clone(),
297|        btrfs_device: parse_json(
298|            "btrfs_device",
299|            &record.session_id,
300|            &record.btrfs_device_json,
301|        )?,
302|        instance: parse_json("instance", &record.session_id, &record.instance_json)?,
303|        session_started_at: record.session_started_at,
304|        last_seen_at: record.last_seen_at,
305|        active: record.active,
306|        expires_at: (record.expires_at != 0).then_some(record.expires_at),
307|        arrival_timestamp: 0,
308|        chain_head_at_arrival: String::new(),
309|        catalog_hash_at_arrival: String::new(),
310|        head_timestamp_at_arrival: 0,
311|    };
312|    if let Some(genesis) = genesis {
313|        // A release bump changes the compiled hash before
314|        // `refresh_drifted_schema_content_hashes` can rewrite the durable row.
315|        // Failing the projection here aborts startup, so the refresh never runs
316|        // and the door never binds. Project the existing arrival claims and let
317|        // that refresh commit the compiled hash.
318|        if !genesis.schema_content_hash.is_empty()
319|            && genesis.schema_content_hash != SCHEMA_CONTENT_HASH.trim()
320|        {
321|            tracing::warn!(
322|                session_id = %record.session_id,
323|                stored = %genesis.schema_content_hash,
324|                expected = %SCHEMA_CONTENT_HASH.trim(),
325|                "identity genesis schema_content_hash drifted; projecting the row so startup refresh can commit"
326|            );
327|        }
328|        sled.arrival_timestamp = genesis.arrival_timestamp;
329|        sled.chain_head_at_arrival = genesis.chain_head_at_arrival.clone();
330|        sled.catalog_hash_at_arrival = genesis.catalog_hash_at_arrival.clone();
331|        sled.head_timestamp_at_arrival = genesis.head_timestamp_at_arrival;
332|    }
333|    validate_sled(&sled)?;
334|    Ok(sled)
