283|pub(super) fn verify_persistent_directory(
284|    path: &Path,
285|    expected: &File,
286|) -> std::result::Result<(), CozoError> {
287|    let current = open_directory(path, false)?.metadata().map_err(native)?;
288|    let expected = expected.metadata().map_err(native)?;
289|    if current.dev() != expected.dev() || current.ino() != expected.ino() {
290|        return Err(err("persistent database directory changed while opening"));
291|    }
292|    Ok(())
