1422|/// Pure request preparation; only the bridge's durable owner may submit it.
1423|pub fn native_creation_body(input: &CreateInstanceInput) -> Result<serde_json::Value> {
1424|    anyhow::ensure!(input.name.is_empty(), "name is server assigned; omit name for ID-N creation");
1425|    anyhow::ensure!(matches!(input.instance_type.as_str(), "container" | "virtual-machine"), "invalid Incus instance type");
1426|    let source = match input.source_mode.as_str() {
1427|        "image" => image_source(&input.image)?,
1428|        "empty" if input.image.is_empty() => serde_json::json!({"type":"none"}),
1429|        _ => anyhow::bail!("source_mode must be image with image, or empty without image"),
1430|    };
1431|    let config = input.config.clone().unwrap_or_default();
1432|    validate_config(&config)?;
1433|    anyhow::ensure!(!config.keys().any(|key| key.starts_with("user.opdbus.")),
1434|        "identity/project metadata is owner assigned, not generic create input");
1435|    let mut devices = BTreeMap::new();
1436|    for named in &input.devices {
1437|        validate_segment(&named.name, "device name")?;
1438|        anyhow::ensure!(devices.insert(named.name.clone(), named.device.to_incus_map()).is_none(), "duplicate Incus device name");
1439|    }
1440|    Ok(serde_json::json!({"type":input.instance_type,"source":source,
1441|        "profiles":input.profiles,"config":config,"devices":devices,"ephemeral":false}))
