1444|/// Native transport only. Admission, allocation and the durable POST fence
1445|/// belong to MutationEngine; no plugin method dispatches here directly.
1446|pub async fn create_reserved_native(body: &serde_json::Value) -> Result<()> {
1447|    let name = body["name"].as_str().context("allocated native name missing")?;
1448|    anyhow::ensure!(numbered_native_name(name)
1449|        && body["config"]["user.opdbus.creation_operation"].as_str().is_some_and(|op| uuid::Uuid::parse_str(op).is_ok_and(|id| id.to_string() == op))
